def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: dict[str, bool] = {}
    history: list[tuple] = []  # stack of revert records for successful, non-undo ops
    rejected: list[int] = []

    def parse_amount(tok: str):
        if not tok or any(c not in "0123456789" for c in tok):
            return None
        return int(tok)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0]
        nargs = len(parts)
        ok = True
        rec = None

        if verb == "open" and nargs == 3:
            name = parts[1]
            n = parse_amount(parts[2])
            if n is None or name in balances:
                ok = False
            else:
                balances[name] = n
                frozen[name] = False
                rec = ("open", name)

        elif verb == "deposit" and nargs == 3:
            name = parts[1]
            n = parse_amount(parts[2])
            if n is None or n <= 0 or name not in balances:
                ok = False
            else:
                balances[name] += n
                rec = ("deposit", name, n)

        elif verb == "withdraw" and nargs == 3:
            name = parts[1]
            n = parse_amount(parts[2])
            if (n is None or n <= 0 or name not in balances
                    or frozen[name] or balances[name] < n):
                ok = False
            else:
                balances[name] -= n
                rec = ("withdraw", name, n)

        elif verb == "transfer" and nargs == 4:
            src, dst = parts[1], parts[2]
            n = parse_amount(parts[3])
            if (n is None or n <= 0 or src == dst
                    or src not in balances or dst not in balances
                    or frozen[src] or balances[src] < n):
                ok = False
            else:
                balances[src] -= n
                balances[dst] += n
                rec = ("transfer", src, dst, n)

        elif verb == "freeze" and nargs == 2:
            name = parts[1]
            if name not in balances or frozen[name]:
                ok = False
            else:
                frozen[name] = True
                rec = ("freeze", name)

        elif verb == "unfreeze" and nargs == 2:
            name = parts[1]
            if name not in balances or not frozen[name]:
                ok = False
            else:
                frozen[name] = False
                rec = ("unfreeze", name)

        elif verb == "undo" and nargs == 1:
            if not history:
                ok = False
            else:
                r = history.pop()
                kind = r[0]
                if kind == "open":
                    name = r[1]
                    del balances[name]
                    del frozen[name]
                elif kind == "deposit":
                    balances[r[1]] -= r[2]
                elif kind == "withdraw":
                    balances[r[1]] += r[2]
                elif kind == "transfer":
                    balances[r[1]] += r[3]
                    balances[r[2]] -= r[3]
                elif kind == "freeze":
                    frozen[r[1]] = False
                elif kind == "unfreeze":
                    frozen[r[1]] = True
            # undo operations are never pushed, so they cannot be reverted

        else:
            ok = False

        if ok:
            if rec is not None:
                history.append(rec)
        else:
            rejected.append(i)

    return dict(balances), rejected
